package app.thawani

internal fun cards5(): List<Card> = listOf(
Card("p25","home_safety","اختناق الفحم والحطب (التسمم بأول أكسيد الكربون)","997","حرج جداً — القاتل الصامت بلا رائحة ولا لون","d","غاز أول أكسيد الكربون ليس له رائحة ولا لون ولا طعم، ويسبب النعاس ثم الإغماء الجماعي أثناء النوم دون شعور بالاختناق.",listOf("عند الشعور بصداع مفاجئ، دوخة، غثيان، أو خمول لدى الجالسين حول الفحم/الحطب: افتح الأبواب والنوافذ فوراً وأخرج الجميع للهواء الطلق.","أخرج المصابين الغائبين عن الوعي إلى الهواء النقي فوراً واتصل بالهلال الأحمر (997) والدفاع المدني (998).","فكّ الملابس الضيقة حول الرقبة والصدر، وافحص التنفس؛ إذا كان المصاب لا يتنفس ابدأ الإنعاش القلبي الرئوي (CPR).","أطفئ مصدر الفحم أو المدفأة أو المولد الكهربائي وأخرجه خارج المكان المغلق.","يجب نقل جميع المتعرضين للمستشفى لتلقي الأكسجين النقي بتركيز 100% حتى لو تحسنت أعراضهم مبدئياً."),listOf("لا تدخل المنقلة أو الفحم المشتعل إلى الغرفة أو الخيمة المغلقة حتى لو تحول بالكامل إلى جمر لا يدخن.","لا تشغّل محرك السيارة أو المولد الكهربائي داخل كراج مغلق متصل بالمنزل."),listOf("تركيب جهاز كاشف غاز أول أكسيد الكربون (CO Detector) في المجالس الشتوية والخيام."),listOf("البيت","الاستراحة","التخييم"),listOf(Link("وزارة الصحة: التعامل مع السموم والغازات","https://www.moh.gov.sa/healthawareness/educationalcontent/firstaid/pages/018.aspx")),listOf()),
Card("p26","home_safety","التسمم الغذائي والجفاف الحاد","937","إسعاف منزلي — تعويض السوائل والأملاح","p","الخطر الأكبر في التسمم الغذائي هو الجفاف السريع وفقدان الأملاح؛ ابدأ بتعويض السوائل بمحلول الجفاف الفموي (ORS) برشفات صغيرة متكررة.",listOf("أوقف تناول الأطعمة الصلبة والألبان والدهون مؤقتاً لإراحة المعدة لبضع ساعات.","أعطِ المصاب محلول الإماهة الفموية (ORS) أو الماء برشفات صغيرة جداً كل 5-10 دقائق.","احتفظ بعينة من الطعام المشتبه به في كيس مغلق إذا ظهرت الأعراض على عدة أفراد في نفس الوقت.","اتصل باستشارات صحة (937) لتقييم الأعراض ومعرفة الأدوية المسموحة.","توجه للطوارئ فوراً إذا ظهر دم في القيء أو الإسهال، أو استمر القيء لأكثر من 24 ساعة، أو ظهرت زغللة بالعين."),listOf("لا تعطِ أدوية إيقاف الإسهال بدون استشارة طبية لأنها قد تحبس البكتيريا والسموم داخل الأمعاء.","لا تعطِ المشروبات الغازية أو العصائر المركزة بالسكر كبديل لمحلول الجفاف الطبي."),listOf("علامات الجفاف الشديد: جفاف الفم واللسان، قلة التبول ولونه الداكن، ودوخة عند الوقوف."),listOf("البيت","الاستراحة","المدرسة"),listOf(Link("وزارة الصحة: خدمة 937","https://www.moh.gov.sa/937/pages/default.aspx")),listOf()),
Card("p27","vehicle_road","تعطل المركبة المفاجئ على الخط السريع","996","سلامة مرورية — تأمين الركاب أولاً","t","الوقوف داخل سيارة متعطلة على كتف طريق سريع خطر جداً؛ أخرج جميع الركاب من الأبواب اليمنى ليقفوا خلف الحاجز المعدني بعيداً عن الطريق.",listOf("شغّل إشارات التحذير الرباعية (الفلشر) فور الشعور بالعطل، وارفع قدمك عن الوقود تدريجياً للاتجاه لأقصى الكتف الأيمن.","أوقف المركبة بأبعد مسافة ممكنة عن مسار الشاحنات والسيارات، ولفّ المقود قليلاً نحو اليمين مع تفعيل فرامل اليد.","أخرج العائلة من الأبواب اليمنى فقط (الجهة البعيدة عن السيارات المسرعة) ليبقوا في مكان آمن خلف الحاجز.","ارتدِ السترة العاكسة وضع مثلث التحذير العاكس خلف المركبة بمسافة 50 إلى 100 متر على الطرق السريعة.","اتصل بأمن الطرق (996) أو الطوارئ الموحد (911) وأرسل إحداثيات موقعك."),listOf("لا تقف خلف المركبة أو في المسار الأيسر لمحاولة إصلاح عطل أو تبديل إطار بجانب السيارات المسرعة.","لا تفتح غطاء المحرك إذا كان هناك دخان كثيف أو بخار ماء يغلي."),listOf("حقيبة طوارئ السيارة: مثلث عاكس، سترة فسفورية، منفاخ إطارات، شاحن بطارية متنقل (Jump Starter)، كشاف، ومياه شرب."),listOf("المركبة والطريق","السفر"),listOf(),listOf()),
Card("p28","vehicle_road","نفاد بطارية المفتاح الذكي أو بطارية السيارة","996","إجراء تقني سريع — تشغيل المركبة في الطوارئ","t","كل مفتاح ذكي يحتوي بداخله على مفتاح معدني مخفي لفتح الباب، وشريحة إلكترونية (RFID/NFC) تعمل بدون بطارية عند تقريبها من نقطة القراءة.",listOf("لفتح باب السيارة: اضغط زر التحرير الصغير في ظهر الريموت الذكي واسحب المفتاح المعدني الميكانيكي المخفي لفتح مقبض باب السائق.","لتشغيل السيارة (الطريقة الأولى): اضغط دواسة الفرامل، وقرّب المفتاح الذكي ليلامس زر التشغيل (Start/Stop) مباشرة بشعار المفتاح لمدة ثانيتين ثم اضغط الزر.","لتشغيل السيارة (الطريقة الثانية في سيارات مثل BYD وغيرها): ضع المفتاح الذكي في العلامة المخصصة له داخل الكونسول الوسطي أو حامل الأكواب، ثم اضغط الفرامل وزر التشغيل.","في حال نفاد بطارية الـ 12 فولت: وصّل الكابل الأحمر بالقطب الموجب (+) أولاً، ثم الأسود بالقطب السالب (-) أو نقطة التأريض المعدنية، وشغّل المركبة.","استبدل بطارية الريموت ببطارية قرصية جديدة (غالباً مقاس CR2032) في أقرب وقت."),listOf("لا تعكس أقطاب كابل الاشتراك (الموجب مع السالب) أبداً لتجنب تلف الكمبيوتر والفيوزات الرئيسية."),listOf("الاحتفاظ ببطارية احتياطية مقاس (CR2032) في درج السيارة دائماً."),listOf("المركبة والطريق","السفر"),listOf(),listOf()),
Card("p29","vehicle_road","انفجار الإطار أثناء القيادة على سرعة عالية","996","حرج — تحكم فوري لمنع انقلاب المركبة","d","إياك والضغط على دواسة الفرامل عند انفجار الإطار؛ الضغط على الفرامل يخل بتوازن السيارة فوراً ويؤدي لانحرافها الحاد أو انقلابها.",listOf("أمسك عجلة القيادة (الدركسون) بكلتا يديك بقوة وثبات شديدين في مسار مستقيم للأمام.","ارفع قدمك عن دواسة الفرامل تماماً؛ وفي الثانية الأولى يمكنك إبقاء لمسة خفيفة جداً على دواسة الوقود للحفاظ على توازن الدفع الأمامي ثم ارفع قدمك تدريجياً.","اترك السيارة تتباطأ من تلقاء نفسها بفعل مقاومة الهواء والإطار التالف دون أي التواء حاد بالمقود.","شغّل إشارات التحذير الرباعية (الفلشر)، وعندما تنخفض السرعة لأقل من 40 كم/ساعة، وجّه السيارة بهدوء تام نحو الكتف الأيمن.","استخدم الفرامل بلطف شديد فقط في الأمتار الأخيرة قبل التوقف الكامل."),listOf("لا تضغط الفرامل بقوة مفاجئة.","لا تلفّ المقود بعنف في الاتجاه المعاكس لسحبة الإطار."),listOf("مراقبة نظام ضغط وحرارة الإطارات (TPMS) وعدم القيادة بإطار منخفض الضغط."),listOf("المركبة والطريق","السفر"),listOf(),listOf()),
Card("p30","vehicle_road","الحوادث المرورية وتأمين الموقع (قاعدة PAS)","911","استجابة ميدانية منظمة — احمِ، أبلغ، أسعف","c","تأمين موقع الحادث أولاً يمنع وقوع تصادمات متتالية؛ لا تخرج مصاباً من السيارة إلا إذا كانت السيارة تحترق أو كان المصاب فاقداً للوعي ولا يتنفس.",listOf("(احمِ - Protect): أوقف سيارتك في مكان آمن بعيداً عن المسار، شغّل الفلشر، ارتدِ السترة العاكسة، وضع مثلث التحذير قبل موقع الحادث بـ 100 متر.","أطفئ محركات السيارات المتصادمة واسحب فرامل اليد لمنع تحركها أو اشتعال الوقود.","(أبلغ - Alert): اتصل فوراً بالطوارئ الموحد (911) أو الهلال الأحمر (997) وحدد الموقع الدقيق، عدد المركبات، وعدد المصابين وحالتهم.","(أسعف - Support): تحدث مع المصابين لطمأنتهم، وأوقف أي نزيف خارجي حاد بالضغط المباشر أو التورنيكيه دون تحريك رقبتهم أو ظهرهم.","في الحوادث البسيطة بدون إصابات: أخرج المركبات من مسار الطريق لتجنب عرقلة السير وتواصل مع (نجم) أو عبر تطبيق توكلنا/أبشر."),listOf("لا تتجمهر أو تقف في منتصف الطريق لتصوير الحادث أو إعاقة وصول سيارات الإسعاف.","لا تسحب مصاباً عالقاً داخل السيارة بالقوة لخطورة إصابته بشلل دائم في العمود الفقري."),listOf("وجود طفاية حريق صالحة ومقص حزام أمان وكاسر زجاج طوارئ في متناول يد السائق."),listOf("المركبة والطريق","السفر"),listOf(Link("المنصة الوطنية: أرقام الطوارئ","https://my.gov.sa/saml.authn/emergency-contact")),listOf())
)
